import { useCallback, useEffect, useRef, useState } from 'react'
import { useAuth } from '@/context/auth-context'
import type { UserProfile } from '@/context/auth-context'
import { useHealth } from '@/hooks/use-health'
import { useRecovery } from '@/context/recovery-context'
import { apiFetch } from '@/utils/api'
import {
  apiWeeklyToSummary,
  buildWeekDays,
  dayHasChartData,
  getWeekStart,
  isValidIsoDate,
  recomputeNormalizedDay,
  resolveInsightsSleepHours,
  type InsightTargets,
  type NormalizedDay,
  type WeeklyInsightSummary,
} from '@/utils/insights-aggregator'
import { buildResourceKey, fetchWithResourceCache } from '@/utils/resource-cache'
import {
  buildWeekKey,
  getCached,
  setCached,
  invalidateWeek,
  TTL_CURRENT_WEEK,
  TTL_PAST_WEEK,
} from '@/utils/insights-cache'
import { getLocalDateString } from '@/utils/date'
import { getLocalTargets, type LocalTargets } from '@/utils/local-targets'
import { registerTodayDataSyncListener, registerTodayTargetsListener } from '@/utils/today-sync'
import { registerTodayReconcileListener } from '@/utils/today-reconcile'
import {
  patchWeeklyInsightSummary,
  registerInsightsMetricsPatchListener,
} from '@/utils/insights-metrics-patch'
import { resolveProteinTargetG } from '@/utils/nutrition'

const DEFAULT_CALORIE_BUDGET = 2000
const DEFAULT_PROTEIN_TARGET = 150

/**
 * Effective protein target — same source of truth the profile/home use:
 * the manually-set value when present, otherwise the goal-aware calc.
 */
function deriveProteinTarget(user: UserProfile | null | undefined): number {
  if (!user) return DEFAULT_PROTEIN_TARGET
  try {
    return resolveProteinTargetG(
      {
        sex:           user.sex,
        age:           user.age,
        heightCm:      user.heightCm,
        weightKg:      user.weightKg,
        activityLevel: user.activityLevel,
        goal:          user.goal,
      },
      user.proteinTarget,
    )
  } catch {
    return DEFAULT_PROTEIN_TARGET
  }
}

/** Effective calorie budget — the profile's budget, then its TDEE goal. */
function deriveCalorieBudget(user: UserProfile | null | undefined): number | null {
  return user?.calorieBudget ?? user?.tdee ?? null
}

function ensureValidTargets(t: InsightTargets, fallbackProtein: number): InsightTargets {
  return {
    ...t,
    calorie_budget: t.calorie_budget > 0 ? t.calorie_budget : DEFAULT_CALORIE_BUDGET,
    protein_target: t.protein_target > 0 ? t.protein_target : fallbackProtein,
  }
}

interface UseWeeklyInsightsResult {
  data:         WeeklyInsightSummary | null
  isLoading:    boolean
  isRefreshing: boolean
  isStale:      boolean
  error:        string | null
  refresh:      () => Promise<void>
}

export function useWeeklyInsights(weekStart?: string): UseWeeklyInsightsResult {
  const { user } = useAuth()
  const { today: healthToday } = useHealth()
  const { today: recoveryToday } = useRecovery()
  const week     = weekStart ?? getWeekStart()
  const isCurrentWeek = week === getWeekStart()

  const [data,         setData]         = useState<WeeklyInsightSummary | null>(null)
  const [isLoading,    setIsLoading]    = useState(true)
  const [isRefreshing, setIsRefreshing] = useState(false)
  const [isStale,      setIsStale]      = useState(false)
  const [error,        setError]        = useState<string | null>(null)

  // Prevent stale async operations from updating state after unmount or week change
  const mountedRef = useRef(true)
  const dataRef    = useRef(data)
  dataRef.current  = data

  useEffect(() => {
    mountedRef.current = true
    return () => { mountedRef.current = false }
  }, [])

  const fetchFromServer = useCallback(async (local: LocalTargets, force = false): Promise<WeeklyInsightSummary> => {
    // Share the summary cache key with summary-context so concurrent fetches
    // deduplicate via the resource-cache inflight map (no duplicate HTTP requests).
    const summaryKey = buildResourceKey('summary-weekly', user?.id ?? '', week)
    const ttl = isCurrentWeek ? TTL_CURRENT_WEEK : TTL_PAST_WEEK

    const [apiData, insightRes] = await Promise.all([
      fetchWithResourceCache<Record<string, unknown>>(
        summaryKey,
        ttl,
        async () => {
          const r = await apiFetch(`/summary/weekly?weekStart=${week}`)
          if (!r.ok) return null
          return r.body as Record<string, unknown>
        },
        { force },
      ),
      apiFetch(`/insights/weekly?weekStart=${week}`)
        .then(r => ({ status: 'fulfilled' as const, value: r }))
        .catch(e => ({ status: 'rejected' as const, reason: e })),
    ])

    if (!apiData) throw new Error('Failed to load weekly summary')

    const insightMessage =
      insightRes.status === 'fulfilled' && insightRes.value.ok
        ? (insightRes.value.body as any)?.insight?.message ?? null
        : null

    const snapshot = (apiData.targets_snapshot ?? {}) as Partial<InsightTargets>
    const fallbackProtein = deriveProteinTarget(user)
    const apiDataWithTargets = {
      ...apiData,
      targets_snapshot: ensureValidTargets(
        {
          calorie_budget: deriveCalorieBudget(user) ?? snapshot.calorie_budget ?? DEFAULT_CALORIE_BUDGET,
          protein_target: user ? fallbackProtein : snapshot.protein_target ?? DEFAULT_PROTEIN_TARGET,
          steps_target:   local.steps_target ?? snapshot.steps_target ?? user?.stepsTarget ?? 10000,
          sleep_target:   local.sleep_target ?? snapshot.sleep_target ?? null,
        },
        fallbackProtein,
      ),
    }

    return apiWeeklyToSummary(apiDataWithTargets, insightMessage, week)
  }, [week, user, isCurrentWeek])

  // Always re-derive each day on cache reads so stale `score` / `met_*` values
  // baked in by older code paths self-heal under the current scoring rules.
  const applyDerivedTargets = useCallback(
    (d: WeeklyInsightSummary, local: LocalTargets): WeeklyInsightSummary => {
      const fallbackProtein = deriveProteinTarget(user)
      const merged: InsightTargets = {
        ...d.targets_snapshot,
        calorie_budget: deriveCalorieBudget(user) ?? d.targets_snapshot.calorie_budget,
        protein_target: user ? fallbackProtein : d.targets_snapshot.protein_target,
        steps_target: local.steps_target ?? d.targets_snapshot.steps_target ?? user?.stepsTarget ?? 10000,
        sleep_target: local.sleep_target ?? d.targets_snapshot.sleep_target,
      }
      const targets = ensureValidTargets(merged, fallbackProtein)
      const rescored = d.days.map(day => recomputeNormalizedDay(day, targets))
      const days = buildWeekDays(rescored, d.week_start)
      const logged = days.filter(x => !x.is_partial)
      return {
        ...d,
        targets_snapshot:  targets,
        days,
        days_met_calories: logged.filter(x => x.met_calories === 'met').length,
        days_met_protein:  logged.filter(x => x.met_protein  === 'met').length,
        days_met_steps:    logged.filter(x => x.met_steps    === 'met').length,
        days_met_sleep:    logged.filter(x => x.met_sleep    === 'met').length,
      }
    },
    [user],
  )

  const applyLiveSleep = useCallback((weekSummary: WeeklyInsightSummary): WeeklyInsightSummary => {
    if (!isCurrentWeek) return weekSummary

    const today = getLocalDateString()
    const weekSleep = weekSummary.days.find((d) => d.date === today)?.sleep_hours
    const liveSleep = resolveInsightsSleepHours(
      healthToday?.sleep_hours,
      weekSleep,
      recoveryToday?.sleep_hours,
    )
    if (!liveSleep) return weekSummary

    const updated = patchWeeklyInsightSummary(
      weekSummary,
      { date: today, sleep_hours: liveSleep },
    )
    return updated ?? weekSummary
  }, [isCurrentWeek, healthToday?.sleep_hours, recoveryToday?.sleep_hours])

  const load = useCallback(async (background = false) => {
    if (!user?.id) return

    const cacheKey = buildWeekKey(user.id, week)
    const ttl      = isCurrentWeek ? TTL_CURRENT_WEEK : TTL_PAST_WEEK
    const local    = await getLocalTargets()

    if (!background) {
      const cached = await getCached<WeeklyInsightSummary>(cacheKey)
      if (cached && isValidIsoDate(cached.data.week_start)) {
        if (mountedRef.current) {
          setData(applyLiveSleep(applyDerivedTargets(cached.data, local)))
          setIsLoading(false)
          setError(null)
        }
        if (!cached.isStale) return
        if (mountedRef.current) setIsStale(true)
        // Fall through to revalidate in background
      }
    }

    try {
      const fresh = await fetchFromServer(local, background)
      await setCached(cacheKey, fresh, ttl)
      if (mountedRef.current) {
        setData(applyLiveSleep(applyDerivedTargets(fresh, local)))
        setIsStale(false)
        setError(null)
      }
    } catch {
      if (mountedRef.current && !data) {
        setError('Could not load weekly insights. Pull down to retry.')
      }
    } finally {
      if (mountedRef.current) {
        setIsLoading(false)
        setIsRefreshing(false)
      }
    }
  }, [user?.id, week, isCurrentWeek, fetchFromServer, applyDerivedTargets, applyLiveSleep, data])

  // Reload when week or user changes
  useEffect(() => {
    setIsLoading(true)
    setData(null)
    setError(null)
    setIsStale(false)
    load()
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [week, user?.id])

  useEffect(() => {
    if (!isCurrentWeek) return
    const current = dataRef.current
    if (!current || !mountedRef.current) return
    const updated = applyLiveSleep(current)
    if (updated !== current) setData(updated)
  }, [isCurrentWeek, applyLiveSleep, healthToday?.sleep_hours, recoveryToday?.sleep_hours])

  useEffect(() => {
    if (!isCurrentWeek) return
    return registerInsightsMetricsPatchListener((patch) => {
      const current = dataRef.current
      if (!current || !mountedRef.current) return
      const updated = patchWeeklyInsightSummary(current, patch)
      if (!updated) return
      setData(updated)
      setIsStale(false)
    })
  }, [isCurrentWeek])

  useEffect(() => {
    if (!isCurrentWeek) return
    return registerTodayDataSyncListener(({ domain }) => {
      if (!user?.id) return
      // Only a 'full' refresh evicts the cached week and refetches. For
      // today-only domains (food, health, water, …) the cached week is still
      // good enough to serve on reload — just flag it stale so an open screen
      // can offer a refresh, without forcing a /summary/weekly + /insights/weekly
      // round-trip on every launch.
      if (domain === 'full') {
        void invalidateWeek(user.id, week)
        void load(true)
      } else if (mountedRef.current) {
        setIsStale(true)
      }
    })
  }, [isCurrentWeek, user?.id, week, load])

  // Write-through reconcile: a today-mutating POST returns the authoritative
  // DailySummary for the edited day. Merge its nutrition fields into the matching
  // NormalizedDay (preserving steps/sleep/water/workout, which DailySummary does
  // NOT carry), re-score, rebuild the week, and write through to cache — no refetch.
  useEffect(() => {
    if (!isCurrentWeek) return
    return registerTodayReconcileListener((bundle) => {
      void (async () => {
        if (!user?.id || !mountedRef.current) return

        const current = dataRef.current
        const date = bundle.date

        // Fallback: no current week in memory, or the reconciled date is outside
        // this week window. We cannot faithfully patch a day we don't hold, so we
        // just flag stale — the sync listener keeps the cache, so a reload serves
        // cached data and revalidates. Correctness over a partial local merge.
        if (
          !current ||
          !isValidIsoDate(date) ||
          date < current.week_start ||
          date > current.week_end
        ) {
          if (mountedRef.current) setIsStale(true)
          return
        }

        const existing = current.days.find(d => d.date === date)
        // Fallback: the day slot isn't present (shouldn't happen for an aligned
        // week, but if it did we'd have no steps/sleep to preserve). Flag stale.
        if (!existing) {
          if (mountedRef.current) setIsStale(true)
          return
        }

        // Derive the same targets applyDerivedTargets uses, so the re-score here
        // matches a cache reload.
        const local = await getLocalTargets()
        if (!mountedRef.current) return
        const fallbackProtein = deriveProteinTarget(user)
        const targets = ensureValidTargets(
          {
            ...current.targets_snapshot,
            steps_target: local.steps_target ?? current.targets_snapshot.steps_target ?? user?.stepsTarget ?? 10000,
            sleep_target: local.sleep_target ?? current.targets_snapshot.sleep_target,
          },
          fallbackProtein,
        )

        // Override only the nutrition fields the DailySummary is authoritative for;
        // preserve steps / sleep_hours / workout_count / water_glasses from cache.
        const mergedDay: NormalizedDay = {
          ...existing,
          calories: bundle.summary.calories_consumed,
          protein:  bundle.summary.protein_consumed,
          carbs:    bundle.summary.carbs_consumed,
          fat:      bundle.summary.fat_consumed,
        }
        const rescoredDay = recomputeNormalizedDay(mergedDay, targets)

        const patchedDays = current.days.map(d => (d.date === date ? rescoredDay : d))
        const days = buildWeekDays(patchedDays, current.week_start)
        const logged = days.filter(x => !x.is_partial)
        const updatedWeek: WeeklyInsightSummary = {
          ...current,
          targets_snapshot:  targets,
          days,
          days_met_calories: logged.filter(x => x.met_calories === 'met').length,
          days_met_protein:  logged.filter(x => x.met_protein  === 'met').length,
          days_met_steps:    logged.filter(x => x.met_steps    === 'met').length,
          days_met_sleep:    logged.filter(x => x.met_sleep    === 'met').length,
        }

        const ttl = isCurrentWeek ? TTL_CURRENT_WEEK : TTL_PAST_WEEK
        await setCached(buildWeekKey(user.id, week), updatedWeek, ttl)
        if (mountedRef.current) {
          setData(updatedWeek)
          setIsStale(false)
        }
      })()
    })
  }, [isCurrentWeek, user, week])

  useEffect(() => {
    if (!isCurrentWeek) return
    return registerTodayTargetsListener(async () => {
      const current = dataRef.current
      if (!current) return
      const local = await getLocalTargets()
      if (mountedRef.current) {
        setData(applyDerivedTargets(current, local))
      }
    })
  }, [isCurrentWeek, applyDerivedTargets])

  const refresh = useCallback(async () => {
    if (!user?.id) return
    setIsRefreshing(true)
    await invalidateWeek(user.id, week)
    await load(true)
  }, [user?.id, week, load])

  return { data, isLoading, isRefreshing, isStale, error, refresh }
}
